head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf35022";
scwin.fm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf35022.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: deleteFile (인자 미해석) */
        if (r["type"] === 'A') { /* TODO Stage2: 행 동작 미정의: scwin.downloadFile (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); return; }
        /* TODO Stage2: 행 동작 미정의: scwin.downloadFile (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35022.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_selectFileList
 * @description select File List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_selectFileList = async function () {
    const sbmOptions = {
        id: "tx_selectFileList",
        method: "post",
        action: "/result/result.do?method=popupAttachedFileView",
        ref: "dma_selectFileListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_deleteFile
 * @description delete File 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_deleteFile = async function () {
    const sbmOptions = {
        id: "tx_deleteFile",
        method: "post",
        action: "/upload/uploadFile.do?method=deleteAttachedFile",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_result_fmt_attachFileSeq
 * @description grd result fmt attach File Seq 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_attachFileSeq = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "type") ?? '') : '');
        if (v === 'A') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: attachFileSeq (image)'), String(data ?? '')) + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: attachFileSeq (image)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.attachFileSeq" }); return String(data ?? ''); }
};

/**
 * @method
 * @name selectFileList
 * @description select File List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectFileList = async function () {
    scwin.fm = (document.InputForm || { elements: [] });
    scwin.fm.action = '/result/result.do?method=popupAttachedFileView';
    scwin.fm.target = '_self';
    await scwin.tx_selectFileList();
};

// [A] 초기 목록 미해결 — jldbnf35022: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name deleteFile_done
 * @description delete File done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteFile_done = async function (data) {
    await $c.win.alert("삭제되었습니다.");
};

/**
 * @method
 * @name deleteFile
 * @description delete File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteFile = async function () {
    const r = await scwin.tx_deleteFile();
    try {
        scwin.deleteFile_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf35022.deleteFile' });
    }
    return r;
};
